@extends('layouts.app') @section('content')<div class="page-head"><div><p class="eyebrow">QUESTION BANK</p><h1>{{$exam->title}}</h1><p class="muted">{{$exam->questions->count()}} questions · {{$exam->questions->sum('points')}} points</p></div></div><div class="panel"><h2>Add question</h2><form method="post" action="{{route('exams.questions.store',$exam)}}" class="form-grid" id="question-form">@csrf<label class="wide">Question text<textarea name="body" rows="4" required></textarea></label><label>Points<input type="number" step="0.1" name="points" value="1" min="0.1" required></label><label>Correct option<input type="number" name="correct" value="0" min="0" max="3" required></label><div class="wide" id="options-list">@for($i=0;$i<4;$i++)<label class="wide option-row">Option {{$i+1}}<span><input name="options[]" required maxlength="500"><button type="button" class="link danger-text remove-option">Remove</button></span></label>@endfor</div><div class="wide"><button type="button" class="btn" id="add-option">Add option</button><button class="btn primary">Add question</button></div></form></div><div class="stack">@foreach($exam->questions as $i=>$q)<article class="panel"><div class="question-head"><strong>Q{{$i+1}}.</strong><span class="badge">{{$q->points}} pt</span><form method="post" action="{{route('exams.questions.destroy',[$exam,$q])}}">@csrf @method('DELETE')<button class="link danger-text">Remove</button></form></div><p>{!!nl2br(e($q->body))!!}</p><ol class="options">@foreach($q->options as $o)<li class="{{$o->is_correct?'correct':''}}">{{$o->label}} @if($o->is_correct)<b>Correct</b>@endif</li>@endforeach</ol></article>@endforeach</div><script>document.addEventListener('DOMContentLoaded',()=>{const list=document.getElementById('options-list'),add=document.getElementById('add-option'),correct=document.querySelector('input[name="correct"]');const sync=()=>{const rows=[...list.querySelectorAll('.option-row')];rows.forEach((row,i)=>{row.firstChild.textContent=`Option ${i+1}`;row.querySelector('input').required=true;row.querySelector('.remove-option').style.display=rows.length>2?'inline':'none';});add.disabled=rows.length>=6;correct.max=rows.length-1;if(Number(correct.value)>=rows.length)correct.value=rows.length-1;};add.addEventListener('click',()=>{const i=list.querySelectorAll('.option-row').length;const row=document.createElement('label');row.className='wide option-row';row.innerHTML=`Option ${i+1}<span><input name="options[]" required maxlength="500"><button type="button" class="link danger-text remove-option">Remove</button></span>`;list.appendChild(row);sync();});list.addEventListener('click',e=>{if(e.target.classList.contains('remove-option')){e.target.closest('.option-row').remove();sync();}});sync();});</script>@endsection